#!/usr/bin/env node
/**
 * Tests for the command-position primitive and the glued-redirect split of hooks/lib/shell-parse.js.
 * Zero dependencies — `node:test` on Node 18+.
 *
 *   node --test tools/guard-shell-command-position.test.mjs
 *
 * `commandPositions(line)` returns one token list per command head of the line (nested ones included),
 * each starting at the head with assignments and wrappers already skipped.
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createRequire } from 'node:module';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const { commandPositions, parseSegments } = createRequire(import.meta.url)(join(ROOT, 'hooks', 'lib', 'shell-parse.js'));

const entries = (line) => commandPositions(line);
const headsOf = (line) => entries(line).map((tokens) => tokens[0]);
const OPERATOR = /^\d*[<>]{1,2}$|^&>>?$/;

test('given a PowerShell assignment of a sqlcmd call, when commandPositions runs, then one entry starts at sqlcmd', () => {
  // Given
  const line = '$r = sqlcmd -S h -Q x';

  // When
  const found = entries(line).filter((tokens) => tokens[0] === 'sqlcmd');

  // Then
  assert.equal(found.length, 1);
  assert.ok(found[0].includes('-S') && found[0].includes('x'));
});

test('given a substitution, an assignment prefix and an export, when commandPositions runs, then sqlcmd is at a command position in each', () => {
  // Given
  const lines = ['x=$(sqlcmd -S h -Q x)', 'r=1 sqlcmd -S h -Q x', 'export X=1; sqlcmd -S h -Q x'];

  for (const line of lines) {
    // When
    const heads = headsOf(line);

    // Then
    assert.ok(heads.includes('sqlcmd'), line);
  }
});

test('given a subshell, a brace group, a substitution, a backtick, a process substitution and a script block, when commandPositions runs, then sqlcmd is a head in each', () => {
  // Given
  const lines = ['(sqlcmd -S h -Q x)', '{ sqlcmd -S h -Q x; }', 'echo $(sqlcmd -S h -Q x)', 'echo `sqlcmd -S h -Q x`',
    'diff <(sqlcmd -S h -Q x) f', '& { sqlcmd -S h -Q x }'];

  for (const line of lines) {
    // When
    const heads = headsOf(line);

    // Then
    assert.ok(heads.includes('sqlcmd'), line);
  }
});

test('given compound-command keywords in shell and PowerShell, when commandPositions runs, then sqlcmd is a head in each', () => {
  // Given
  const lines = ['if true; then sqlcmd -S h; fi', 'while x; do sqlcmd -S h; done', 'if x; then a; else sqlcmd -S h; fi', '! sqlcmd -S h',
    'if ($a) { sqlcmd -S h }', 'foreach ($x in 1) { sqlcmd -S h }'];

  for (const line of lines) {
    // When
    const heads = headsOf(line);

    // Then
    assert.ok(heads.includes('sqlcmd'), line);
  }
});

test('given redirects glued to their words, when the line is tokenized, then the operator and its target are separate tokens', () => {
  // Given
  const cases = [['cat<.env', '.env'], ['cat 0<.env', '.env'], ['echo x>f', 'f'], ['echo x>>f', 'f'], ['echo x 2>f', 'f'], ['echo x&>f', 'f']];

  for (const [line, target] of cases) {
    // When
    const segments = parseSegments(line);
    const tokens = segments.flat();

    // Then
    assert.equal(segments.length, 1, line);
    assert.ok(tokens.includes(target), line);
    assert.ok(tokens.some((t) => OPERATOR.test(t)), line);
  }
});

test('given a quoted angle bracket, when the line is tokenized, then no redirect is produced', () => {
  // Given
  const cases = [['echo "a>b"', ['echo', 'a>b']], ["grep 'x<y'", ['grep', 'x<y']]];

  for (const [line, expected] of cases) {
    // When
    const segments = parseSegments(line);

    // Then
    assert.deepEqual(segments, [expected], line);
  }
});

test('given a nesting deeper than MAX_DEPTH, when commandPositions runs, then it terminates and still returns the outer heads', () => {
  // Given
  let line = 'sqlcmd -S h';
  for (let i = 0; i < 6; i += 1) line = `echo $(${line})`;

  // When
  const heads = headsOf(line);

  // Then
  assert.equal(heads[0], 'echo');
  assert.ok(heads.length >= 2);
});
